  "    var map = { t_party: 'party', t_pair: 'pair', t_console: 'console', t_game: 'game', t_temp: 'temp', t_fav: 'fav', t_queue: 'queue', t_lib: 'lib', t_lib_help: 'lib_help',\n"
  "      add_open: 'add', imp_open: 'imp', l_title: 'title', l_url: 'url', l_cover: 'cover', l_plat: 'plat', l_tid: 'tid', l_ver: 'ver', l_desc: 'desc', save: 'save', cancel: 'cancel',\n"
  "      i_title: 'imp', i_help: 'i_help', l_file: 'file', i_paste_s: 'paste', i_paste_go: 'import_go', l_link: 'link', i_link_go: 'link_go', i_unlink: 'unlink', t_games: 'games',\n"
  "      t_addmusic: 'addmusic', t_addmusic_help: 'addmusic_help', l_mfiles: 'mfiles', l_mlink: 'mlink', m_link_go: 'play', t_mfiles: 'onconsole',\n"
  "      t_up: 'up', t_up_help: 'up_help', l_upfile: 'up_file', l_updir: 'up_dir', l_updir_s: 'up_dir_s', l_upname: 'up_name', up_wait: 'up_wait', up_cancel: 'cancel',\n"
  "      l_upinst: 'up_inst', w1t: 'w1t', w1: 'w1', w2t: 'w2t', w2: 'w2', w3t: 'w3t', w3: 'w3', jh_t: 'jh_t', jh: 'jh', jdl_l: 'jdl', jcp_l: 'jcp', jtry_l: 'jtry' };\n"
  "    Object.keys(map).forEach(function (k) { var el = $(k); if (el) el.textContent = tx(map[k]); });\n"
  "    each('.l_music', function (el) { el.textContent = tx('music'); });\n"
  "    each('.l_lib', function (el) { el.textContent = tx('lib'); });\n"
  "    $('toggle').title = tx('play');\n"
  "    jsonHelp();\n"
  "  }\n"
  "  // Esempio scaricabile: gli stessi campi che la console accetta (lib.c)\n"
  "  var EXAMPLE = { name: 'My games', games: [\n"
  "    { title: 'Homebrew Game', url: 'https://example.com/games/homebrew-game.pkg', cover: 'https://example.com/covers/homebrew-game.jpg',\n"
  "      images: ['https://example.com/shots/homebrew-game-1.jpg'], platform: 'PS4', title_id: 'CUSA12345', version: '1.00', description: 'A short description of the game.', type: 'pkg' },\n"
  "    { title: 'My Emulator', url: 'https://example.com/apps/my-emulator.zip', cover: 'https://example.com/covers/my-emulator.png', platform: 'PS5', version: '2.1', type: 'zip' },\n"
  "    { title: 'Payload Tool', url: 'https://example.com/payloads/tool.elf', type: 'elf' }\n"
  "  ] };\n"
  "  function jsonHelp() {\n"
  "    var tb = $('jfields'); if (!tb) return; tb.textContent = '';\n"
  "    [['title', 'f_title'], ['url', 'f_url'], ['cover', 'f_cover'], ['images', 'f_images'], ['platform', 'f_platform'], ['title_id', 'f_tid'], ['version', 'f_ver'], ['description', 'f_desc'], ['type', 'f_type']].forEach(function (r) {\n"
  "      var tr = el('tr'); tr.appendChild(el('td', '', r[0])); tr.appendChild(el('td', '', tx(r[1]))); tb.appendChild(tr);\n"
  "    });\n"
  "    $('jex').textContent = JSON.stringify(EXAMPLE, null, 2);\n"
  "  }\n"
  "  function each(sel, fn) { Array.prototype.forEach.call(document.querySelectorAll(sel), fn); }\n"
  "  function icon(id) { return '<svg aria-hidden=\"true\"><use href=\"#' + id + '\"/></svg>'; }\n"
  "  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; }\n"
  "  function bg(url) { return 'url(\"' + url.replace(/[\"\\\\\\n]/g, encodeURIComponent) + '\")'; }\n"
  "  // le icone dei giochi caricati le serve la console stessa (127.0.0.1 dal suo punto di vista)\n"
  "  function img(u) { return u.indexOf('http://127.0.0.1:9095/') === 0 ? u.slice(21) + '&k=' + encodeURIComponent(tok) : u; }\n"
  "  pickLang((navigator.language || 'en'));\n"
  "  texts();\n"
  "\n"
  "  var tok = ''; try { tok = localStorage.getItem('omega-remote') || ''; } catch (e) {}\n"
  "  var st = null, qseq = -1, games = [], editId = '';\n"
  "\n"
  "  function api(method, path, body) {\n"
  "    return fetch(path, { method: method, headers: { 'content-type': 'application/json', 'x-omega-token': tok }, body: body ? JSON.stringify(body) : undefined, cache: 'no-store' })\n"
  "      .then(function (r) { if (r.status === 401) { tok = ''; showPair(); throw new Error('auth'); } return r.json().then(function (j) { j._status = r.status; return j; }); });\n"
  "  }\n"
  "  function showPair() { $('pair').hidden = false; $('app').hidden = true; $('tabs_top').hidden = true; setTimeout(function () { $('pinin').focus(); }, 50); }\n"
  "  function showApp() { $('pair').hidden = true; $('app').hidden = false; $('tabs_top').hidden = false; }\n"
  "  function conn(on) { var c = $('conn'); c.textContent = on ? L.on : L.off; c.className = 'conn ' + (on ? 'on' : 'off'); }\n"
  "\n"
  "  function pair() {\n"
  "    var pin = $('pinin').value.replace(/\\D/g, '');\n"
  "    if (pin.length < 6) { $('pinin').focus(); return; }\n"
  "    fetch('/v1/pair', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ pin: pin }) })\n"
  "      .then(function (r) { return r.json().then(function (j) { return [r.status, j]; }); })\n"
  "      .then(function (x) {\n"
  "        if (x[0] === 200 && x[1].token) { tok = x[1].token; try { localStorage.setItem('omega-remote', tok); } catch (e) {} showApp(); tab(saved); loadFavs(); loadMusicFiles(); poll(); }\n"
  "        else { $('perr').textContent = x[1].error === 'locked' ? L.locked : L.bad; $('pinin').select(); }\n"
  "      }).catch(function () { $('perr').textContent = L.off; });\n"
  "  }\n"
  "  $('pairbtn').onclick = pair;\n"
  "  $('pinin').addEventListener('input', function () { $('perr').textContent = ''; if (this.value.replace(/\\D/g, '').length === 6) pair(); });\n"
  "  $('pinin').addEventListener('keydown', function (e) { if (e.key === 'Enter') pair(); });\n"
  "\n"
  "  // ------------------------------------------------------------- schede --\n"
  "  function tab(which) {\n"
  "    $('music').hidden = which !== 'music'; $('lib').hidden = which !== 'lib';\n"
  "    each('[data-tab]', function (b) { b.classList.toggle('on', b.getAttribute('data-tab') === which); });\n"
  "    try { localStorage.setItem('omega-remote-tab', which); } catch (e) {}\n"
  "    if (which === 'lib') loadLib();\n"
  "  }\n"
  "  each('[data-tab]', function (b) { b.onclick = function () { tab(b.getAttribute('data-tab')); window.scrollTo(0, 0); }; });\n"
  "\n"
  "  // ------------------------------------------------------------- musica --\n"
  "  function fmt(s) { s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + ('0' + s % 60).slice(-2); }\n"
  "  function render() {\n"
  "    if (!st) return;\n"
  "    $('title').textContent = st.stream_title || st.title || '—';\n"
  "    $('artist').textContent = st.stream_title ? st.title : [st.artist, st.album].filter(Boolean).join(' · ');\n"
  "    var s = $('state'), live = st.state === 'playing' && st.live;\n"
  "    s.textContent = st.state === 'playing' ? (st.live ? L.live : fmt(st.pos) + ' / ' + fmt(st.dur)) : (L[st.state] || st.state);\n"
  "    s.className = 'st' + (live ? ' live' : '');\n"
  "    $('prog').style.width = (!st.live && st.dur > 0 ? Math.min(100, st.pos / st.dur * 100) : 0) + '%';\n"
  "    var playing = st.state === 'playing' || st.state === 'loading';\n"
  "    var tg = $('toggle'), want = playing ? 'i-pause' : 'i-play';\n"
  "    if (tg.getAttribute('data-i') !== want) { tg.innerHTML = icon(want); tg.setAttribute('data-i', want); }\n"
  "    $('shuffle').classList.toggle('on', !!st.shuffle);\n"
  "    $('repeat').classList.toggle('on', st.repeat > 0);\n"
  "    $('repeat').classList.toggle('one', st.repeat === 2);\n"
  "    if (document.activeElement !== $('vol')) { $('vol').value = st.volume; volFill(); }\n"
  "    var c = $('cover');\n"
  "    var art = st.has_cover ? '/v1/cover?i=' + st.index + '&t=' + encodeURIComponent(st.title) + '&k=' + encodeURIComponent(tok) : (/^https?:\\/\\/(?!127\\.)/.test(st.cover) && st.cover.indexOf('/api/v1/') < 0 ? st.cover : '');\n"
  "    if (c.getAttribute('data-art') !== art) { c.style.backgroundImage = art ? bg(art) : ''; c.classList.toggle('has', !!art); c.setAttribute('data-art', art); }\n"
  "    if (st.seq !== qseq) { qseq = st.seq; api('GET', '/v1/queue').then(renderQueue).catch(function () {}); }\n"
  "    else markCurrent();\n"
  "  }\n"
  "  var qcur = -1;\n"
  "  function markCurrent() {\n"
  "    if (!st || st.index === qcur) return;\n"
  "    var items = $('queue').children;\n"
  "    for (var i = 0; i < items.length; i++) setCur(items[i], i === st.index);\n"
  "    qcur = st.index;\n"
  "  }\n"
  "  function setCur(li, on) {\n"
  "    if (!li.querySelector('.n')) return;\n"
  "    li.classList.toggle('cur', on);\n"
  "    var n = li.querySelector('.n');\n"
  "    n.innerHTML = on ? '<span class=\"eq\"><i></i><i></i><i></i></span>' : '';\n"
  "    if (!on) n.textContent = n.getAttribute('data-n');\n"
  "  }\n"
  "  function renderQueue(q) {\n"
  "    var ul = $('queue'); ul.textContent = ''; qcur = -1;\n"
  "    $('qn').textContent = q.items.length ? q.items.length : '';\n"
  "    if (!q.items.length) { ul.appendChild(el('li', 'empty', L.empty)); return; }\n"
  "    q.items.forEach(function (it, i) {\n"
  "      var li = el('li');\n"
  "      var n = el('span', 'n', String(i + 1)); n.setAttribute('data-n', String(i + 1)); li.appendChild(n);\n"
  "      li.appendChild(el('span', 'x', it.title + (it.artist ? ' · ' + it.artist : '')));\n"
  "      if (it.dur > 0) li.appendChild(el('small', '', fmt(it.dur)));\n"
  "      li.onclick = function () { cmd('jump', i); };\n"
  "      ul.appendChild(li);\n"
  "      if (i === q.index) setCur(li, true);\n"
  "    });\n"
  "    qcur = q.index;\n"
  "  }\n"
  "  function cmd(c, v) { api('POST', '/v1/cmd', { cmd: c, value: v === undefined ? 0 : v }).then(function (j) { st = j; render(); }).catch(function () {}); }\n"
  "  $('toggle').onclick = function () { cmd('toggle'); };\n"
  "  $('next').onclick = function () { cmd('next'); };\n"
  "  $('prev').onclick = function () { cmd('prev'); };\n"
  "  $('shuffle').onclick = function () { cmd('shuffle', st && st.shuffle ? 0 : 1); };\n"
  "  $('repeat').onclick = function () { cmd('repeat', st ? (st.repeat + 1) % 3 : 1); };\n"
  "  function volFill() { $('vol').style.setProperty('--p', $('vol').value + '%'); }\n"
  "  $('vol').oninput = volFill;\n"
  "  $('vol').onchange = function () { cmd('volume', +$('vol').value); };\n"
  "\n"
  "  function loadFavs() {\n"
  "    api('GET', '/v1/favorites').then(function (j) {\n"
  "      var ul = $('favs'); ul.textContent = '';\n"
  "      $('favbox').hidden = !j.fav || !j.fav.length;\n"
  "      (j.fav || []).forEach(function (f, i) {\n"
  "        var li = el('li'); li.innerHTML = icon('i-radio'); li.appendChild(el('span', '', f.name)); li.title = f.name;\n"
  "        li.onclick = function () { api('POST', '/v1/queue', { mode: 'replace', start: i, items: j.fav.map(function (x) { return { url: x.url, title: x.name, album: 'Radio', source: 'radio', id: x.id }; }) }).then(function (s) { st = s; render(); }); };\n"
  "        ul.appendChild(li);\n"
  "      });\n"
  "    }).catch(function () {});\n"
  "  }\n"
  "\n"
  "  // ------------------------------------------------- musica dal telefono --\n"
  "  var musicDir = '';\n"
  "  function loadMusicFiles() {\n"
  "    api('GET', '/v1/music/files').then(function (j) {\n"
  "      musicDir = j.dir || '';\n"
  "      var ul = $('mfiles'); ul.textContent = '';\n"
  "      (j.files || []).forEach(function (f, i) {\n"
  "        var li = el('li');\n"
  "        li.appendChild(el('span', 'x', f.name));\n"
  "        li.appendChild(el('small', '', (f.size / 1048576).toFixed(1) + ' MB'));\n"
  "        var del = el('button', 'ibtn danger'); del.type = 'button'; del.innerHTML = icon('i-trash'); del.title = L.del;\n"
  "        del.onclick = function (ev) { ev.stopPropagation(); if (confirm(L.del + ': ' + f.name + '?')) api('POST', '/v1/music/delete', { name: f.name }).then(loadMusicFiles); };\n"
  "        li.appendChild(del);\n"
  "        li.onclick = function () {\n"
  "          var items = j.files.map(function (x) { return { url: musicDir + '/' + x.name, title: x.name.replace(/\\.[^.]+$/, ''), source: 'file' }; });\n"
  "          api('POST', '/v1/queue', { mode: 'replace', start: i, items: items }).then(function (s2) { st = s2; render(); });\n"
  "        };\n"
  "        ul.appendChild(li);\n"
  "      });\n"
  "      $('mfiles_box').hidden = !(j.files || []).length;\n"
  "    }).catch(function () {});\n"
  "  }\n"
  "  function upload(files, i, done) {\n"
  "    if (i >= files.length) { $('upbar').hidden = true; $('mok').textContent = L.uploaded + done; loadMusicFiles(); return; }\n"
  "    var f = files[i], x = new XMLHttpRequest();\n"
  "    $('upbar').hidden = false; $('upprog').style.width = '0'; $('mok').textContent = L.uploading + f.name + ' (' + (i + 1) + '/' + files.length + ')';\n"
  "    x.open('POST', '/v1/music/upload?name=' + encodeURIComponent(f.name));\n"
  "    x.setRequestHeader('x-omega-token', tok);\n"
  "    x.upload.onprogress = function (e) { if (e.lengthComputable) $('upprog').style.width = (e.loaded / e.total * 100) + '%'; };\n"
  "    x.onload = function () { if (x.status !== 200) $('merr').textContent = L.upfail + f.name; upload(files, i + 1, done + (x.status === 200 ? 1 : 0)); };\n"
  "    x.onerror = function () { $('merr').textContent = L.upfail + f.name; upload(files, i + 1, done); };\n"
  "    x.send(f);\n"
  "  }\n"
  "  function sendFiles(list) { $('merr').textContent = ''; upload(Array.prototype.slice.call(list || []), 0, 0); }\n"
  "  $('m_files').onchange = function () { sendFiles(this.files); this.value = ''; };\n"
  "  // dal PC si possono anche trascinare i file sul riquadro\n"
  "  var drop = $('m_drop');\n"
  "  ['dragenter', 'dragover'].forEach(function (n) { drop.addEventListener(n, function (e) { e.preventDefault(); drop.classList.add('over'); }); });\n"
  "  ['dragleave', 'drop'].forEach(function (n) { drop.addEventListener(n, function () { drop.classList.remove('over'); }); });\n"
  "  drop.addEventListener('drop', function (e) { e.preventDefault(); if (e.dataTransfer && e.dataTransfer.files.length) sendFiles(e.dataTransfer.files); });\n"
  "  function playLink() {\n"
  "    var u = $('m_link').value.trim(); if (!/^https?:\\/\\//i.test(u)) { $('merr').textContent = L.need; return; }\n"
  "    $('merr').textContent = '';\n"
  "    var name = u.split('?')[0].split('/').pop() || u; try { name = decodeURIComponent(name); } catch (e) {}\n"
  "    api('POST', '/v1/queue', { mode: 'next', play: true, items: [{ url: u, title: name, source: 'link' }] }).then(function (s2) { st = s2; render(); $('m_link').value = ''; });\n"
  "  }\n"
  "  $('m_link_go').onclick = playLink;\n"
  "  $('m_link').addEventListener('keydown', function (e) { if (e.key === 'Enter') playLink(); });\n"
  "\n"
  "  // ----------------------------------------------------------- libreria --\n"
  "  function loadLib() {\n"
  "    api('GET', '/v1/library').then(function (j) {\n"
  "      games = j.items || [];\n"
  "      var src = j.source || {};\n"
  "      $('i_unlink').hidden = !src.url;\n"
  "      if (src.url && !$('i_link').value) $('i_link').value = src.url;\n"
  "      if (j.seq === libseq) return;\n"
  "      libseq = j.seq;\n"
  "      $('gn').textContent = games.length ? games.length : '';\n"
  "      var ul = $('games'); ul.textContent = '';\n"
  "      if (!games.length) { ul.appendChild(el('li', 'none', L.nogames)); return; }\n"
  "      games.forEach(function (g) {\n"
  "        var li = el('li', 'game');\n"
  "        var cv = el('div', 'cv'); cv.innerHTML = icon('i-games');\n"
  "        if (g.cover) { cv.style.backgroundImage = bg(img(g.cover)); cv.classList.add('has'); }\n"
  "        li.appendChild(cv);\n"
  "        if (g.origin !== 'manual') li.appendChild(el('span', 'tag', g.origin === 'json' ? L.from_link : g.origin === 'upload' ? tx('from_upload') : L.from_import));\n"
  "        var tools = el('div', 'tools');\n"
  "        var ed = el('button', 'ibtn'); ed.type = 'button'; ed.innerHTML = icon('i-edit'); ed.title = L.edit; ed.setAttribute('aria-label', L.edit);\n"
  "        ed.onclick = function () { openForm(g); };\n"
  "        var del = el('button', 'ibtn danger'); del.type = 'button'; del.innerHTML = icon('i-trash'); del.title = L.del; del.setAttribute('aria-label', L.del);\n"
  "        del.onclick = function () { if (confirm(L.delq)) api('POST', '/v1/library/remove', { id: g.id }).then(loadLib); };\n"
  "        tools.appendChild(ed); tools.appendChild(del); li.appendChild(tools);\n"
  "        var info = el('div', 'info');\n"
  "        info.appendChild(el('b', '', g.title));\n"
  "        info.appendChild(el('span', '', [g.platform, g.title_id, g.version, (g.kind || '').toUpperCase()].filter(Boolean).join(' · ') || ' '));\n"
  "        var ib = el('button', 'btn inst'); ib.type = 'button'; ib.innerHTML = icon('i-down'); ib.appendChild(el('span', '', tx('inst')));\n"
  "        ib.onclick = function () {\n"
  "          ib.disabled = true;\n"
  "          api('POST', '/v1/library/install', { id: g.id }).then(function (r) {\n"
  "            ib.lastChild.textContent = r._status === 200 ? '✓' : '✕';\n"
  "            if (r._status === 200) $('upok').textContent = tx('inst_ok'); else alert(tx('inst_fail'));\n"
  "            setTimeout(function () { ib.disabled = false; ib.lastChild.textContent = tx('inst'); }, 4000);\n"
  "          }).catch(function () { ib.disabled = false; });\n"
  "        };\n"
  "        info.appendChild(ib);\n"
  "        li.appendChild(info);\n"
  "        ul.appendChild(li);\n"
  "      });\n"
  "    }).catch(function () {});\n"
  "  }\n"
  "  var editUpload = false;\n"
  "  function openForm(g) {\n"
  "    editId = g ? g.id : '';\n"
  "    editUpload = !!(g && g.origin === 'upload');\n"
  "    $('g_url').hidden = $('l_url').hidden = editUpload;\n"
  "    $('f_title').textContent = g ? L.f_edit : L.f_new;\n"
  "    $('g_title').value = g ? g.title : ''; $('g_url').value = g ? g.url : ''; $('g_cover').value = g ? g.cover : '';\n"
  "    $('g_plat').value = g ? g.platform : ''; $('g_tid').value = g ? g.title_id : ''; $('g_ver').value = g ? g.version : ''; $('g_desc').value = g ? g.description : '';\n"
  "    $('ferr').textContent = ''; $('form').hidden = false; $('imp').hidden = true;\n"
  "    $('form').scrollIntoView({ behavior: 'smooth', block: 'start' });\n"
  "    $('g_title').focus({ preventScroll: true });\n"
  "  }\n"
  "  $('add_open_b').onclick = function () { openForm(null); };\n"
  "  $('cancel').onclick = function () { $('form').hidden = true; };\n"
  "  $('save').onclick = function () {\n"
  "    var g = { title: $('g_title').value.trim(), url: $('g_url').value.trim(), cover: $('g_cover').value.trim(), platform: $('g_plat').value,\n"
  "              title_id: $('g_tid').value.trim().toUpperCase(), version: $('g_ver').value.trim(), description: $('g_desc').value.trim() };\n"
  "    if (editId) g.id = editId;\n"
  "    if (!g.title || (!editUpload && !/^https?:\\/\\//i.test(g.url))) { $('ferr').textContent = L.need; return; }\n"
  "    api('POST', '/v1/library/item', g).then(function (j) {\n"
  "      if (j._status === 200) { $('form').hidden = true; libseq = -1; loadLib(); }\n"
  "      else $('ferr').textContent = L.need;\n"
  "    });\n"
  "  };\n"
  "\n"
  "  // importazione JSON\n"
  "  $('imp_open_b').onclick = function () { $('imp').hidden = false; $('form').hidden = true; $('iok').textContent = $('ierr').textContent = ''; $('imp').scrollIntoView({ behavior: 'smooth', block: 'start' }); };\n"
  "  // esito con i numeri: aggiunti, aggiornati (↻), saltati perché senza titolo o link (✕)\n"
  "  function counts(a, u, k) { return a + (u ? ' · ↻ ' + u : '') + (k ? ' · ✕ ' + k : ''); }\n"
  "  function imported(j) {\n"
  "    if (j._status === 200) { $('iok').textContent = L.added + counts(j.added, j.updated, j.skipped); $('ierr').textContent = ''; libseq = -1; loadLib(); }\n"
  "    else { $('ierr').textContent = L.badjson + (j.skipped ? ' (✕ ' + j.skipped + ')' : ''); $('iok').textContent = ''; }\n"
  "  }\n"
  "  function importText(txt) {\n"
  "    var data;\n"
  "    // il BOM dei file salvati su Windows fa fallire JSON.parse\n"
  "    try { data = JSON.parse(String(txt).replace(/^\\uFEFF/, '')); } catch (e) { $('ierr').textContent = L.badjson; $('iok').textContent = ''; return; }\n"
  "    // si manda il JSON così com'è (array, {\"items\"}, FPKGi {\"DATA\"}...): la console lo riconosce\n"
  "    api('POST', '/v1/library/import', Array.isArray(data) ? { items: data } : data).then(imported).catch(function () {});\n"
  "  }\n"
  "  // dopo \"Collega\": si guarda la libreria finché la sincronizzazione non finisce\n"
  "  function watchSync(from, tries) {\n"
  "    setTimeout(function () {\n"
  "      api('GET', '/v1/library').then(function (j) {\n"
  "        var src = j.source || {};\n"
  "        libseq = -1; loadLib();\n"
  "        if (src.last_sync === from && tries > 0) return watchSync(from, tries - 1);\n"
  "        var m = /^ok (\\d+) (\\d+)/.exec(src.status || '');\n"
  "        if (m) { $('iok').textContent = L.linked + counts(m[1], 0, +m[2]); $('ierr').textContent = ''; }\n"
  "        else if (src.status) { $('ierr').textContent = (src.status === 'fetch_failed' ? L.off : L.badjson) + ' (' + src.status + ')'; $('iok').textContent = ''; }\n"
  "      });\n"
  "    }, 2000);\n"
  "  }\n"
  "  $('i_file').onchange = function () {\n"
  "    var f = this.files && this.files[0]; if (!f) return;\n"
  "    var r = new FileReader(); r.onload = function () { importText(String(r.result)); }; r.readAsText(f);\n"
  "    this.value = '';\n"
  "  };\n"
  "  $('i_paste_go').onclick = function () { importText($('i_text').value); };\n"
  "  $('jdl').onclick = function () {\n"
  "    var b = new Blob([JSON.stringify(EXAMPLE, null, 2) + '\\n'], { type: 'application/json' });\n"
  "    var a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = 'omega-games-example.json';\n"
  "    document.body.appendChild(a); a.click(); setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 500);\n"
  "  };\n"
  "  $('jcp').onclick = function () {\n"
  "    var t = JSON.stringify(EXAMPLE, null, 2), done = function () { $('jcp_l').textContent = tx('copied'); setTimeout(function () { $('jcp_l').textContent = tx('jcp'); }, 1500); };\n"
  "    if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(t).then(done, function () {});\n"
  "    else { var ta = el('textarea'); ta.value = t; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); done(); } catch (e) {} ta.remove(); }\n"
  "  };\n"
  "  $('jtry').onclick = function () { $('i_text').value = JSON.stringify(EXAMPLE, null, 2); $('i_text').closest('details').open = true; $('i_text').focus(); };\n"
  "  $('i_link_go').onclick = function () {\n"
  "    var u = $('i_link').value.trim();\n"
  "    if (!/^https?:\\/\\//i.test(u)) { $('ierr').textContent = L.need; return; }\n"
  "    api('GET', '/v1/library').then(function (j0) {\n"
  "      var from = (j0.source || {}).last_sync;\n"
  "      api('POST', '/v1/library/source', { url: u }).then(function () { $('iok').textContent = L.syncing; $('ierr').textContent = ''; watchSync(from, 15); });\n"
  "    });\n"
  "  };\n"
  "  $('i_unlink').onclick = function () { api('POST', '/v1/library/source', { url: '' }).then(function () { $('i_link').value = ''; libseq = -1; loadLib(); }); };\n"
  "\n"
  "  // ------------------------------------- giochi da questo dispositivo --\n"
  "  var upX = null, upStop = false;\n"
  "  function size(b) { return b >= 1073741824 ? (b / 1073741824).toFixed(1) + ' GB' : (b / 1048576).toFixed(1) + ' MB'; }\n"
  "  function fill(t, o) { return t.replace(/\\{(\\w+)\\}/g, function (m, k) { return o[k] !== undefined ? o[k] : m; }); }\n"
  "  function upMsg(ok, err) { $('upok').textContent = ok || ''; $('uperr').textContent = err || ''; }\n"
  "  function upEnd() { upX = null; $('upbox').hidden = true; $('up_file').disabled = $('up_dir').disabled = false; try { upRelease(); } catch (e) {} }\n"
  "  // list: [{file, path}] — path relativo dentro il lotto.\n"
  "  // Ogni file riprende da dove era arrivato (status + &o=): se la rete cade, la\n"
  "  // console si blocca o il servizio si riavvia, si riprova con attese crescenti.\n"
  "  var RETRY = [2, 4, 8, 15, 30, 30, 60, 60, 60, 60, 60, 60, 60, 60, 60];   // ~12 minuti in tutto\n"
  "  function upStart(list) {\n"
  "    if (!list.length || upX) return;\n"
  "    upMsg('', '');\n"
  "    var total = list.reduce(function (a, x) { return a + x.file.size; }, 0);\n"
  "    // stessi file scelti di nuovo = stesso lotto: riprende da dove si era fermato\n"
  "    var sig = list.map(function (x) { return x.path + ':' + x.file.size; }).join('|'), h = 0;\n"
  "    for (var c = 0; c < sig.length; c++) h = (h * 31 + sig.charCodeAt(c)) | 0;\n"
  "    var key = 'omega-up-' + (h >>> 0).toString(36), batch = '';\n"
  "    try { batch = localStorage.getItem(key) || ''; } catch (e) {}\n"
  "    if (!/^[a-z0-9]{6,32}$/.test(batch)) {\n"
  "      batch = ''; for (var i = 0; i < 12; i++) batch += 'abcdefghijklmnopqrstuvwxyz0123456789'[Math.floor(Math.random() * 36)];\n"
  "      try { localStorage.setItem(key, batch); } catch (e) {}\n"
  "    }\n"
  "    var resumed = false; try { resumed = !!localStorage.getItem(key + '-started'); } catch (e) {}\n"
  "    api('GET', '/v1/library/space').then(function (sp) {\n"
  "      if (sp.free >= 0 && total + 268435456 > sp.free && !resumed) { upMsg('', fill(tx('up_space'), { a: size(sp.free), b: size(total) })); return; }\n"
  "      upStop = false; $('upbox').hidden = false; $('up_file').disabled = $('up_dir').disabled = true;\n"
  "      var sent = 0, fails = 0, timer = null;\n"
  "      var show = function (i, done) {\n"
  "        $('up_txt').textContent = fill(tx('up_sending'), { n: i + 1, t: list.length, a: size(sent + done), b: size(total) });\n"
  "        $('up_prog').style.width = (total ? (sent + done) / total * 100 : 0) + '%';\n"
  "      };\n"
  "      var retry = function (again) {\n"
  "        if (upStop) { upEnd(); return; }\n"
  "        if (fails >= RETRY.length) { upEnd(); upMsg('', tx('up_fail') + tx('up_gaveup')); return; }\n"
  "        var wait = RETRY[fails++], left = wait;\n"
  "        retryNow = function () { again(); };\n"
  "        var tick = function () {\n"
  "          if (upStop) return;\n"
  "          $('up_txt').textContent = fill(tx('up_retry'), { s: left, k: fails, m: RETRY.length });\n"
  "          if (left-- <= 0) again(); else timer = setTimeout(tick, 1000);\n"
  "        };\n"
  "        tick();\n"
  "      };\n"
  "      var finish = function () {\n"
  "        api('POST', '/v1/library/upload/done', { b: batch, title: $('up_name').value.trim(), install: $('up_inst').checked }).then(function (r) {\n"
  "          if (r._status === 409) { retry(finish); return; }   // un file non è ancora completo sul disco\n"
  "          upEnd();\n"
  "          try { localStorage.removeItem(key); localStorage.removeItem(key + '-started'); } catch (e) {}\n"
  "          if (r.homebrew) upMsg(fill(tx('up_hb'), { name: r.homebrew }), '');\n"
  "          else if (r.added) { upMsg(tx(r.installing ? 'up_installing' : 'up_lib'), ''); $('up_name').value = ''; libseq = -1; loadLib(); }\n"
  "          else upMsg('', /unknown|title_id/.test(r.error || '') ? tx('up_unknown') : tx('up_fail') + (r.error || ''));\n"
  "        }).catch(function () { retry(finish); });\n"
  "      };\n"
  "      var send = function (i) {\n"
  "        if (upStop) { upEnd(); return; }\n"
  "        if (i >= list.length) { finish(); return; }\n"
  "        var f = list[i].file, path = list[i].path;\n"
  "        // quanto è già arrivato si chiede solo dopo un errore o alla ripresa di un lotto:\n"
  "        // con migliaia di file piccoli una richiesta in più per file pesa\n"
  "        var ask = fails > 0 || resumed ? api('GET', '/v1/library/upload/status?b=' + batch + '&p=' + encodeURIComponent(path)) : Promise.resolve({ have: 0, done: false });\n"
  "        ask.then(function (st) {\n"
  "          if (st.done && st.have === f.size) { sent += f.size; fails = 0; send(i + 1); return; }\n"
  "          var off = st.have > 0 && st.have <= f.size ? st.have : 0;\n"
  "          var x = new XMLHttpRequest(); upX = x;\n"
  "          x.open('POST', '/v1/library/upload?b=' + batch + '&p=' + encodeURIComponent(path) + '&o=' + off + '&sb=' + sent + '&tb=' + total);\n"
  "          x.setRequestHeader('x-omega-token', tok);\n"
  "          var last = Date.now();\n"
  "          var watch = setInterval(function () { if (Date.now() - last > 30000) { clearInterval(watch); x.abort(); } }, 2000);   // fermo da 30 s: si riprova\n"
  "          show(i, off);\n"
  "          x.upload.onprogress = function (e) { last = Date.now(); show(i, off + e.loaded); if (e.loaded > 1048576) fails = 0; };\n"
  "          x.onload = function () {\n"
  "            clearInterval(watch);\n"
  "            if (x.status === 200) { sent += f.size; fails = 0; send(i + 1); return; }\n"
  "            if (x.status === 507) { upEnd(); upMsg('', fill(tx('up_space'), { a: '?', b: size(total) })); return; }\n"
  "            retry(function () { send(i); });\n"
  "          };\n"
  "          x.onerror = x.onabort = function () { clearInterval(watch); if (upStop) { upEnd(); return; } retry(function () { send(i); }); };\n"
  "          x.send(off ? f.slice(off) : f);\n"
  "        }).catch(function () { retry(function () { send(i); }); });\n"
  "      };\n"
  "      upStopTimer = function () { if (timer) clearTimeout(timer); };\n"
  "      // il telefono non deve spegnere lo schermo: in background il browser ferma la pagina\n"
  "      var lock = null;\n"
  "      try { if (navigator.wakeLock) navigator.wakeLock.request('screen').then(function (l) { lock = l; }).catch(function () {}); } catch (e) {}\n"
  "      upRelease = function () { try { if (lock) lock.release(); } catch (e) {} lock = null; };\n"
  "      // tornando sulla pagina dopo una pausa si riprova subito, senza aspettare l'attesa in corso\n"
  "      upWake = function () { if (timer && !upStop) { clearTimeout(timer); timer = null; fails = Math.max(fails, 1); retryNow(); } };\n"
  "      try { localStorage.setItem(key + '-started', '1'); } catch (e) {}\n"
  "      send(0);\n"
  "    }).catch(function () { upMsg('', tx('up_fail')); });\n"
  "  }\n"
  "  var upStopTimer = function () {}, upRelease = function () {}, upWake = function () {}, retryNow = function () {};\n"
  "  document.addEventListener('visibilitychange', function () {\n"
  "    if (document.visibilityState === 'visible') upWake();\n"
  "  });\n"
  "  $('up_cancel').onclick = function () { upStop = true; upStopTimer(); if (upX) upX.abort(); upEnd(); };\n"
  "  $('up_file').onchange = function () { var f = this.files && this.files[0]; if (f) upStart([{ file: f, path: f.name }]); this.value = ''; };\n"
  "  $('up_dir').onchange = function () {\n"
  "    var l = Array.prototype.map.call(this.files || [], function (f) { return { file: f, path: f.webkitRelativePath || f.name }; });\n"
  "    upStart(l); this.value = '';\n"
  "  };\n"
  "  if (!('webkitdirectory' in document.createElement('input')) || /iPhone|iPad|iPod/.test(navigator.userAgent)) {\n"
  "    $('up_drop2').onclick = function (e) { e.preventDefault(); upMsg('', tx('up_nodir')); };\n"
  "  }\n"
  "  // dal PC: file o cartelle trascinati sui riquadri\n"
  "  function walk(entry, pre, out) {\n"
  "    return new Promise(function (res) {\n"
  "      if (entry.isFile) entry.file(function (f) { out.push({ file: f, path: pre + f.name }); res(); }, function () { res(); });\n"
  "      else if (entry.isDirectory) {\n"
  "        var r = entry.createReader(), all = [];\n"
  "        (function more() {\n"
  "          r.readEntries(function (es) {\n"
  "            if (!es.length) { Promise.all(all.map(function (e) { return walk(e, pre + entry.name + '/', out); })).then(res); return; }\n"
  "            all = all.concat(Array.prototype.slice.call(es)); more();\n"
  "          }, function () { res(); });\n"
  "        })();\n"
  "      } else res();\n"
  "    });\n"
  "  }\n"
  "  ['up_drop', 'up_drop2'].forEach(function (id) {\n"
  "    var d = $(id);\n"
  "    ['dragenter', 'dragover'].forEach(function (n) { d.addEventListener(n, function (e) { e.preventDefault(); d.classList.add('over'); }); });\n"
  "    ['dragleave', 'drop'].forEach(function (n) { d.addEventListener(n, function () { d.classList.remove('over'); }); });\n"
  "    d.addEventListener('drop', function (e) {\n"
  "      e.preventDefault();\n"
  "      var items = e.dataTransfer && e.dataTransfer.items, out = [];\n"
  "      if (!items || !items.length || !items[0].webkitGetAsEntry) { if (e.dataTransfer.files[0]) upStart([{ file: e.dataTransfer.files[0], path: e.dataTransfer.files[0].name }]); return; }\n"
  "      var entries = Array.prototype.map.call(items, function (it) { return it.webkitGetAsEntry(); }).filter(Boolean);\n"
  "      Promise.all(entries.map(function (en) { return walk(en, '', out); })).then(function () { upStart(out); });\n"
  "    });\n"
  "  });\n"
  "\n"
  "  // ------------------------------------------------------------- ciclo --\n"
  "  function poll() {\n"
  "    if (!tok) { showPair(); return; }\n"
  "    api('GET', '/v1/state').then(function (j) { st = j; conn(true); showApp(); render(); })\n"
  "      .catch(function (e) { if (e.message !== 'auth') conn(false); });\n"
  "    api('GET', '/v1/system').then(function (j) {\n"
  "      if (j.lang) pickLang(j.lang);\n"
  "      $('game').textContent = j.game || L.none;\n"
  "      $('temp').textContent = j.cpu_t > 0 ? j.cpu_t + ' °C' : '—';\n"
  "    }).catch(function () {});\n"
  "    api('GET', '/v1/voice').then(function (v) {\n"
  "      $('partybox').hidden = !v.active;\n"
  "      if (!v.active) return;\n"
  "      var k = v.mic === 'none' ? 'p_nomic' : v.muted ? 'p_muted' : v.mic === 'silent' ? 'p_silent' : 'p_on';\n"
  "      $('pstate').textContent = tx(k).replace('{p}', v.party + (v.talking && v.talking.length ? ' · 🔊 ' + v.talking.join(', ') : ''));\n"
  "      $('pmic').textContent = tx(v.muted ? 'p_unmute' : 'p_mute'); $('pmic').hidden = v.mic === 'none';\n"
  "      $('pmic').onclick = function () { api('POST', '/v1/voice', { cmd: 'toggle' }).then(poll); };\n"
  "      $('pleave').textContent = tx('p_leave');\n"
  "      $('pleave').onclick = function () { if (confirm(tx('p_leaveq'))) api('POST', '/v1/voice', { cmd: 'leave' }).then(poll); };\n"
  "    }).catch(function () {});\n"
  "  }\n"
  "  var saved = 'music'; try { saved = localStorage.getItem('omega-remote-tab') || 'music'; } catch (e) {}\n"
  "  if (tok) { showApp(); tab(saved); loadFavs(); loadMusicFiles(); poll(); } else showPair();\n"
  "  setInterval(poll, 2000);\n"
  "  setInterval(function () { if (!$('app').hidden) loadFavs(); }, 30000);\n"
  "})();\n"
  "</script>\n"
  "</body>\n"
  "</html>\n"
  "\n";
const size_t REMOTE_HTML_LEN = sizeof REMOTE_HTML - 1;
